create or replace function hrm.tg_pay_component_versions_bases() returns trigger
language plpgsql as $fn$
declare
    v_company uuid;
    v_bad uuid;
begin
    if cardinality(new.base_component_ids) = 0 then
        return new;
    end if;
    select company_id into v_company from hrm.pay_components where id = new.component_id;
    if new.component_id = any (new.base_component_ids) then
        raise exception 'pay component %: a component cannot be based on itself', new.component_id
            using errcode = '23514', constraint = 'ck_pay_component_versions_bases';
    end if;
    select b into v_bad from unnest(new.base_component_ids) as b
     where not exists (select 1 from hrm.pay_components c where c.id = b and c.company_id = v_company) limit 1;
    if v_bad is not null then
        raise exception 'pay component %: base component % does not exist in the company', new.component_id, v_bad
            using errcode = '23514', constraint = 'ck_pay_component_versions_bases';
    end if;
    if exists (
        with recursive walk(id) as (
            select unnest(new.base_component_ids)
            union
            select unnest(v.base_component_ids)
              from walk w
              join hrm.pay_component_versions v on v.component_id = w.id
               and v.id <> new.id
               and v.valid_from <= new.valid_from and (v.valid_to is null or v.valid_to > new.valid_from)
        )
        select 1 from walk where id = new.component_id) then
        raise exception 'pay component %: its base components lead back to it', new.component_id
            using errcode = '23514', constraint = 'ck_pay_component_versions_bases';
    end if;
    return new;
end
$fn$;
